SELECT id,nickname,username,phone,user_role,is_admin,balance,points,performance_score,carrier_verify_status,buyer_verify_status,banned_until,invite_tier,created_at FROM t_profiles

 AND (nickname LIKE CONCAT('%',#{keyword},'%') OR username LIKE CONCAT('%',#{keyword},'%') OR phone LIKE CONCAT('%',#{keyword},'%') OR id=#{keyword})

 ORDER BY created_at DESC LIMIT #{limit}
